WITH ChemistryEnrollmentStats AS ( SELECT tso.OFFER_DEPT_NAME, AVG(tso.NUM_ENROLLED_STUDENTS) AS avg_enrollment, VARIANCE(tso.NUM_ENROLLED_STUDENTS) AS enrollment_variance FROM TIP_SUBJECT_OFFERED tso JOIN TIP_DETAIL td ON tso.TERM_CODE = td.TERM_CODE WHERE td.RECORD_COUNT > 0 AND tso.OFFER_DEPT_NAME = 'Chemistry' GROUP BY tso.OFFER_DEPT_NAME ORDER BY enrollment_variance DESC ), DegreeDeptUnitStats AS ( SELECT sd.DEPARTMENT_NAME, AVG(ccso.TOTAL_UNITS) AS avg_total_units, VARIANCE(ccso.TOTAL_UNITS) AS var_total_units FROM SIS_DEPARTMENT sd JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON sd.DEPARTMENT_CODE = ccso.DEPARTMENT_CODE WHERE sd.IS_DEGREE_GRANTING = 'Y' AND ccso.ACADEMIC_YEAR = 2022 AND sd.DEPARTMENT_CODE <> '7' GROUP BY sd.DEPARTMENT_NAME ORDER BY sd.DEPARTMENT_NAME ), CombinedStats AS ( SELECT OFFER_DEPT_NAME AS DEPARTMENT_NAME, avg_enrollment, enrollment_variance, NULL AS avg_total_units, NULL AS var_total_units, 'ChemistryEnrollment' AS Reason FROM ChemistryEnrollmentStats UNION ALL SELECT DEPARTMENT_NAME, NULL, NULL, avg_total_units, var_total_units, 'DegreeDeptUnits' AS Reason FROM DegreeDeptUnitStats ) SELECT DEPARTMENT_NAME, avg_enrollment, enrollment_variance, avg_total_units, var_total_units, Reason FROM CombinedStats ORDER BY DEPARTMENT_NAME;